package com.feynman.backend;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;

/**
 * Entry point for the Feynman learning-platform backend.
 *
 * <p>The backend evaluates a user's notebooks/pages and scores how well the
 * topic appears to be understood, following the Feynman technique (if you can
 * explain it simply, you understand it). Scores replace the front-end's
 * hard-coded {@code progress.ts} placeholder values.</p>
 */
@SpringBootApplication
@ConfigurationPropertiesScan
public class FeynmanBackendApplication {

    public static void main(String[] args) {
        SpringApplication.run(FeynmanBackendApplication.class, args);
    }
}

package com.feynman.backend.controller;

import com.feynman.backend.service.OpenAiEvaluationService.EvaluationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Translates uncaught exceptions into RFC 7807 {@link ProblemDetail} responses.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setTitle("Invalid request");
        pd.setDetail(ex.getBindingResult().getAllErrors().stream()
                .findFirst()
                .map(err -> err.getDefaultMessage())
                .orElse("Validation failed"));
        return pd;
    }

    @ExceptionHandler(EvaluationException.class)
    public ProblemDetail handleEvaluation(EvaluationException ex) {
        log.error("Evaluation failed", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_GATEWAY);
        pd.setTitle("Evaluation failed");
        pd.setDetail(ex.getMessage());
        return pd;
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail handleGeneric(Exception ex) {
        log.error("Unexpected error", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR);
        pd.setTitle("Internal error");
        pd.setDetail("An unexpected error occurred.");
        return pd;
    }
}

package com.feynman.backend.dto;

import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Request payload for {@code POST /api/evaluate}.
 *
 * <p>The frontend sends its full set of notebooks and pages; the backend
 * returns an understanding score (0–100) for every page and an aggregate
 * score for every notebook. When {@code notebookId} is provided, only that
 * notebook (and its pages) is evaluated.</p>
 *
 * @param notebookId Optional filter — evaluate only this notebook when set.
 */
public record EvaluateRequest(
        @NotNull List<NotebookDto> notebooks,
        @NotNull List<PageDto> pages,
        String notebookId
) {
}

package com.feynman.backend.dto;

import java.util.Map;

/**
 * Response payload for {@code POST /api/evaluate}.
 *
 * <p>Scores are split so the frontend can merge page- and notebook-level
 * results independently, matching the shape consumed by {@code setLiveScores}.
 * Each map is keyed by the entity id (matching the frontend seed ids).</p>
 */
public record EvaluationResponse(
        Map<String, ScoreDto> pageScores,
        Map<String, ScoreDto> notebookScores
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code Notebook} type.
 */
public record NotebookDto(
        String id,
        String title,
        String color
) {
}

package com.feynman.backend.dto;

import java.util.List;

/**
 * Mirrors the frontend {@code Page} type. Represents a single page whose
 * understanding we want to score.
 */
public record PageDto(
        String id,
        String notebookId,
        String parentId,
        String title,
        String content,
        List<TextBoxDto> boxes,
        Integer order
) {
    /** Combined free text of the page (content + all text boxes). */
    public String combinedText() {
        StringBuilder sb = new StringBuilder();
        if (content != null) {
            sb.append(content);
        }
        if (boxes != null) {
            for (TextBoxDto box : boxes) {
                if (box != null && box.text() != null && !box.text().isBlank()) {
                    sb.append("\n").append(box.text());
                }
            }
        }
        return sb.toString().trim();
    }
}

package com.feynman.backend.dto;

/**
 * A single understanding score for a notebook or page.
 *
 * @param score              Understanding percentage, 0–100.
 * @param understandingNotes Short human-readable explanation of the score.
 */
public record ScoreDto(
        int score,
        String understandingNotes
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code TextBox} type: a free-floating text box on the
 * page canvas. Only {@code text} matters for evaluation.
 */
public record TextBoxDto(
        String id,
        Double x,
        Double y,
        String text,
        Double width
) {
}

import type { Notebook, Page } from '@/types'
import { evaluateNotes } from '@/services/evaluationApi'
import type { EvaluationResult } from '@/services/evaluationApi'

/**
 * @deprecated Use `@/services/evaluationApi` directly.
 *
 * Kept as a thin re-export so any existing imports of `@/api/evaluation`
 * continue to resolve to the single canonical client.
 */
export type { Score, EvaluationResult } from '@/services/evaluationApi'
export { evaluateNotes } from '@/services/evaluationApi'

/** @deprecated Prefer `evaluateNotes(notebooks, pages, notebookId?)`. */
export async function evaluateNotebooks(payload: {
  notebooks: Notebook[]
  pages: Page[]
  notebookId?: string
}): Promise<EvaluationResult> {
  return evaluateNotes(payload.notebooks, payload.pages, payload.notebookId)
}

import type { Notebook, Page } from '@/types'

/**
 * Client for the Feynman backend evaluation API.
 *
 * The base URL is configurable via `VITE_API_BASE_URL`; by default it is empty
 * so requests hit the Vite dev proxy (`/api → http://localhost:8080`).
 */
const API_BASE_URL = import.meta.env.VITE_API_BASE_URL ?? ''

/** A single understanding score returned by the backend. */
export interface Score {
  score: number
  understandingNotes: string
}

/** Response shape of {@code POST /api/evaluate}. */
export interface EvaluationResult {
  /** Page id → score. */
  pageScores: Record<string, Score>
  /** Notebook id → aggregate score. */
  notebookScores: Record<string, Score>
}

/**
 * Ask the backend to grade how well the user understands each topic.
 *
 * @param notebooks  All notebooks (or the subset to evaluate).
 * @param pages      All pages (the backend filters by `notebookId` if given).
 * @param notebookId Optional — evaluate only this notebook and its pages.
 */
export async function evaluateNotes(
  notebooks: Notebook[],
  pages: Page[],
  notebookId?: string
): Promise<EvaluationResult> {
  const res = await fetch(`${API_BASE_URL}/api/evaluate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ notebooks, pages, notebookId })
  })

  if (!res.ok) {
    throw new Error(`Evaluation request failed: ${res.status} ${res.statusText}`)
  }

  return (await res.json()) as EvaluationResult
}

  return pages.map((p) => ({ ...p, boxes: Array.isArray(p.boxes) ? p.boxes : [] }))
